def criar_empresas_a_partir_de_clientes_faturados(apps, schema_editor):
    Cliente = apps.get_model('lavajato', 'Cliente')
    EmpresaFaturada = apps.get_model('lavajato', 'EmpresaFaturada')

    for cliente in Cliente.objects.filter(tipo='FATURADO', empresa_faturada__isnull=True):
        empresa, _ = EmpresaFaturada.objects.get_or_create(
            nome=cliente.nome,
            defaults={
                'documento': cliente.documento,
                'telefone': cliente.telefone,
                'observacoes': cliente.observacoes,
            },
        )
        cliente.empresa_faturada = empresa
        cliente.save(update_fields=['empresa_faturada'])


